/* =============================================
   GLASSMORPHISM BLOGGER THEME
   ============================================= */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Fira+Code:wght@400;500&display=swap');

/* --- CSS Custom Properties (Glassmorphism Theme) --- */
:root {
  /* Glassmorphism Background Colors */
  --bg: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
  --bg-solid: #0f0c29;
  --bg-card: rgba(255, 255, 255, 0.05);
  --bg-card-hover: rgba(255, 255, 255, 0.1);
  --bg-nav: rgba(255, 255, 255, 0.08);
  --bg-glass: rgba(255, 255, 255, 0.03);

  /* Text Colors */
  --text: rgba(255, 255, 255, 0.9);
  --text-muted: rgba(255, 255, 255, 0.6);
  --text-heading: #ffffff;

  /* Accent Colors - Vibrant gradient palette */
  --accent: #00d4ff;
  --accent-secondary: #7b2cbf;
  --accent-hover: #80e5ff;
  --accent-gradient: linear-gradient(135deg, #00d4ff 0%, #7b2cbf 100%);

  /* Glassmorphism Borders */
  --border: rgba(255, 255, 255, 0.1);
  --border-light: rgba(255, 255, 255, 0.2);
  --border-glow: rgba(0, 212, 255, 0.3);

  /* Code Blocks */
  --code-bg: rgba(0, 0, 0, 0.4);
  --code-text: #e2e8f0;
  --tag-bg: rgba(123, 44, 191, 0.3);
  --tag-text: #e0c3fc;

  /* Shadows for depth */
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  --shadow-hover: 0 20px 60px rgba(0, 0, 0, 0.4);
  --shadow-glow: 0 0 40px rgba(0, 212, 255, 0.15);

  /* Border Radius */
  --radius: 20px;
  --radius-sm: 12px;
  --radius-lg: 28px;

  /* Navigation */
  --nav-height: 80px;

  /* Glassmorphism Blur */
  --blur: blur(20px);
  --blur-heavy: blur(40px);
}

/* --- Base Reset & Typography --- */
*, *::before, *::after { 
  box-sizing: border-box; 
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  background-attachment: fixed;
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.7;
  margin: 0;
  min-height: 100vh;
  overflow-wrap: break-word;
}

/* Animated background mesh effect */
body::before {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: 
    radial-gradient(ellipse at 20% 20%, rgba(0, 212, 255, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 80%, rgba(123, 44, 191, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 50%, rgba(255, 0, 128, 0.05) 0%, transparent 70%);
  pointer-events: none;
  z-index: -1;
}

h1, h2, h3, h4, h5, h6 {
  color: var(--text-heading);
  font-weight: 700;
  line-height: 1.3;
  margin-top: 0;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: all 0.3s ease;
}

a:hover { 
  color: var(--accent-hover); 
  text-shadow: 0 0 20px rgba(0, 212, 255, 0.5);
}

p { margin: 0 0 1.2em; }

img { 
  max-width: 100%; 
  height: auto; 
  border-radius: var(--radius-sm); 
}

/* --- Utility --- */
.hidden { display: none; }
.invisible { visibility: hidden; }
.clearboth { clear: both; }

/* ============================================
   GLASSMORPHISM NAVIGATION BAR
   ============================================ */
.centered-top-container {
  background: var(--bg-nav);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: var(--shadow);
}

.centered-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: var(--nav-height);
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 32px;
}

.blog-name h1 {
  font-size: 26px;
  font-weight: 800;
  margin: 0;
  letter-spacing: -0.02em;
  color: var(--text-heading);
  text-shadow: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.blog-name h1 a { 
  color: var(--accent);
  position: relative;
  display: inline-block;
  text-decoration: none;
}

.blog-name h1 a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent-gradient);
  transition: width 0.3s ease;
}

.blog-name h1 a:hover::after {
  width: 100%;
}

.blog-name h1 a:hover {
  color: var(--accent-hover);
}

/* Glassmorphism Navbar styling */
.custom-nav-links {
  display: flex;
  gap: 12px;
  align-items: center;
}

.custom-nav-links a {
  color: var(--text-heading);
  font-weight: 500;
  font-size: 15px;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: 1px solid transparent;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.custom-nav-links a::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.1) 0%, rgba(123, 44, 191, 0.1) 100%);
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: -1;
}

.custom-nav-links a:hover {
  border-color: var(--border-light);
  transform: translateY(-2px);
  box-shadow: 0 4px 20px rgba(0, 212, 255, 0.2);
}

.custom-nav-links a:hover::before {
  opacity: 1;
}

/* Hide default blogger nav elements to maintain clean design */
.hamburger-menu-container, .search, #page_list_top { display: none !important; }

/* ============================================
   PAGE BODY & LAYOUT
   ============================================ */
.page_body {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.centered-bottom {
  margin: 0 auto;
  max-width: 1200px;
  padding: 48px 32px;
  width: 100%;
}

/* ============================================
   GLASSMORPHISM PROJECT CARDS (HOMEPAGE GRID)
   ============================================ */
body.feed-view .widget.Blog .blog-posts {
  display: grid !important;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)) !important;
  gap: 40px !important;
  align-items: stretch;
  margin-top: 20px;
}

body.feed-view .widget.Blog .post-outer-container {
  width: 100% !important;
}

body.feed-view .widget.Blog .post-outer {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  overflow: hidden;
  position: relative;
}

body.feed-view .widget.Blog .post-outer::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.05),
    transparent
  );
  transition: left 0.7s ease;
}

body.feed-view .widget.Blog .post-outer:hover {
  transform: translateY(-8px) scale(1.02);
  box-shadow: var(--shadow-hover), var(--shadow-glow);
  border-color: var(--border-glow);
  background: var(--bg-card-hover);
}

body.feed-view .widget.Blog .post-outer:hover::before {
  left: 100%;
}

body.feed-view .widget.Blog .post {
  padding: 28px !important;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

/* Card Thumbnail with Glassmorphism */
body.feed-view .snippet-thumbnail {
  margin: -28px -28px 24px -28px;
  height: 240px;
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--border);
}

body.feed-view .snippet-thumbnail::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background: linear-gradient(to top, rgba(15, 12, 41, 0.8), transparent);
  pointer-events: none;
}

body.feed-view .snippet-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.5s ease;
}

body.feed-view .post-outer:hover .snippet-thumbnail img {
  transform: scale(1.1);
}

/* Post Title */
.post-title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.35;
  margin: 0 0 16px;
}

.post-title a { 
  color: var(--text-heading); 
  position: relative;
  display: inline-block;
}

.post-title a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent-gradient);
  transition: width 0.3s ease;
}

.post-title a:hover { 
  color: var(--accent); 
}

.post-title a:hover::after {
  width: 100%;
}

/* Post Meta */
.post-header {
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 12px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.post-header .byline {
  margin: 0;
}

.post-header .byline.post-author,
.post-header .byline.post-timestamp {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.post-header .post-author-label,
.post-header .byline-label {
  color: var(--text-muted);
}

.post-header a { color: var(--text-muted); }

/* Glassmorphism Read More Button */
.read-more-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.15) 0%, rgba(123, 44, 191, 0.15) 100%);
  color: var(--accent) !important;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 14px;
  text-align: center;
  transition: all 0.3s ease;
  margin-top: auto;
  backdrop-filter: blur(10px);
  position: relative;
  overflow: hidden;
}

.read-more-btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: var(--accent-gradient);
  transition: left 0.3s ease;
  z-index: -1;
}

.read-more-btn:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 212, 255, 0.3);
  color: #fff !important;
}

.read-more-btn:hover::before {
  left: 0;
}

/* ============================================
   GLASSMORPHISM SINGLE POST / DOCUMENTATION VIEW
   ============================================ */
body.item-view .widget.Blog .blog-posts .post-outer {
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 48px;
  box-shadow: var(--shadow);
}

.post-body {
  color: var(--text);
  font-size: 17px;
  line-height: 1.9;
  margin-top: 32px;
}

/* Glassmorphism Code Blocks & Pre */
.post-body pre, .post-body code {
  font-family: 'Fira Code', 'JetBrains Mono', monospace;
  font-size: 14px;
}

.post-body pre {
  background: var(--code-bg);
  backdrop-filter: blur(10px);
  color: var(--code-text);
  border-radius: var(--radius-sm);
  padding: 24px;
  overflow-x: auto;
  margin: 28px 0;
  border: 1px solid var(--border);
  box-shadow: inset 0 2px 10px rgba(0, 0, 0, 0.3);
}

.post-body code {
  background: var(--tag-bg);
  color: var(--tag-text);
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 14px;
  border: 1px solid rgba(123, 44, 191, 0.3);
}

.post-body pre code {
  background: none;
  padding: 0;
  border: none;
}

/* Glassmorphism Blockquote */
.post-body blockquote {
  border-left: 4px solid var(--accent);
  margin: 28px 0;
  padding: 20px 28px;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.05) 0%, rgba(123, 44, 191, 0.05) 100%);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  color: var(--text-heading);
  font-style: italic;
  backdrop-filter: blur(10px);
  border-top: 1px solid var(--border);
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

/* Glassmorphism Tags / Labels */
.byline.post-labels a {
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.15) 0%, rgba(123, 44, 191, 0.15) 100%);
  color: var(--tag-text);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 16px;
  margin-right: 8px;
  display: inline-block;
  margin-bottom: 8px;
  border: 1px solid var(--border);
  backdrop-filter: blur(10px);
  transition: all 0.3s ease;
}

.byline.post-labels a:hover {
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.3) 0%, rgba(123, 44, 191, 0.3) 100%);
  border-color: var(--accent);
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(0, 212, 255, 0.2);
}

/* Post Snippet Styling */
.post-snippet {
  color: var(--text-muted);
  font-size: 15px;
  margin-top: 12px;
  margin-bottom: 24px;
  flex-grow: 1;
  line-height: 1.7;
}

/* Read More Button Arrow Animation */
.read-more-btn .arrow {
  display: inline-block;
  transition: transform 0.3s ease;
}

.read-more-btn:hover .arrow {
  transform: translateX(4px);
}

/* ============================================
   GLASSMORPHISM SIDEBAR
   ============================================ */
.sidebar-container {
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  border-left: 1px solid var(--border);
  padding: 28px;
}

@media screen and (min-width: 1024px) {
  body.item-view #main {
    display: flex;
    gap: 48px;
  }
  body.item-view .widget.Blog {
    flex: 1;
    min-width: 0;
  }
  .sidebar-container {
    width: 320px;
    flex-shrink: 0;
    border: none;
    background: transparent;
    padding: 0;
  }
}

.sidebar-container .widget {
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  margin-bottom: 28px;
  transition: all 0.3s ease;
}

.sidebar-container .widget:hover {
  border-color: var(--border-light);
  box-shadow: var(--shadow-glow);
}

.sidebar-container .widget h2.title {
  color: var(--text-heading);
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 12px;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.sidebar-container ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar-container li {
  margin-bottom: 14px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  transition: all 0.3s ease;
}

.sidebar-container li:last-child {
  border-bottom: none;
}

.sidebar-container li:hover {
  padding-left: 8px;
}

.sidebar-container li a {
  color: var(--text);
  transition: all 0.3s ease;
  display: block;
}

.sidebar-container li a:hover {
  color: var(--accent);
  text-shadow: 0 0 10px rgba(0, 212, 255, 0.3);
}

/* Glassmorphism Profile Widget */
.widget.Profile .profile-img {
  border-radius: 50%;
  width: 120px;
  height: 120px;
  display: block;
  margin: 0 auto 20px;
  border: 3px solid transparent;
  background: linear-gradient(var(--bg-solid), var(--bg-solid)) padding-box,
              var(--accent-gradient) border-box;
  box-shadow: 0 8px 30px rgba(0, 212, 255, 0.2);
  transition: all 0.3s ease;
}

.widget.Profile .profile-img:hover {
  transform: scale(1.05);
  box-shadow: 0 12px 40px rgba(0, 212, 255, 0.3);
}

.widget.Profile .profile-data {
  text-align: center;
}

.widget.Profile .profile-data dt { 
  font-weight: 700; 
  color: var(--text-heading); 
  font-size: 20px;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.widget.Profile .profile-data dd { 
  margin: 12px 0; 
  color: var(--text-muted); 
  font-size: 14px;
  line-height: 1.6;
}

.widget.Profile .profile-link { display: none; } /* Hide default visit profile link */

/* ============================================
   GLASSMORPHISM CUSTOM FOOTER
   ============================================ */
.custom-dev-footer {
  margin-top: auto;
  border-top: 1px solid var(--border);
  padding: 48px 32px;
  text-align: center;
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  position: relative;
}

.custom-dev-footer::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 200px;
  height: 1px;
  background: var(--accent-gradient);
}

.custom-dev-footer p {
  margin: 0 0 16px 0;
  color: var(--text-muted);
  font-size: 14px;
}

.custom-dev-footer .footer-links {
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}

.custom-dev-footer .footer-links a {
  color: var(--text);
  font-weight: 600;
  font-size: 14px;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(10px);
  transition: all 0.3s ease;
}

.custom-dev-footer .footer-links a:hover {
  color: var(--accent);
  border-color: var(--accent);
  transform: translateY(-3px);
  box-shadow: 0 8px 25px rgba(0, 212, 255, 0.2);
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.1) 0%, rgba(123, 44, 191, 0.1) 100%);
}

/* Hide Default Footer */
#footer { display: none; }

/* ============================================
   GLASSMORPHISM HOMEPAGE HEADER
   ============================================ */
.homepage-header {
  margin-bottom: 40px;
  padding: 40px;
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.homepage-header::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(0, 212, 255, 0.05) 0%, transparent 60%);
  animation: rotate 25s linear infinite;
  pointer-events: none;
  opacity: 0.6;
}

@keyframes rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.homepage-header h2 {
  font-size: 42px;
  font-weight: 800;
  margin: 0 0 16px 0;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  position: relative;
  z-index: 1;
}

.homepage-header p {
  color: var(--text-muted);
  font-size: 18px;
  margin: 0;
  position: relative;
  z-index: 1;
}

@media screen and (max-width: 768px) {
  .homepage-header {
    padding: 28px 20px;
    margin-bottom: 28px;
  }

  .homepage-header h2 {
    font-size: 28px;
  }

  .homepage-header p {
    font-size: 15px;
  }
}

/* ============================================
   GLASSMORPHISM RESPONSIVE DESIGN
   ============================================ */
@media screen and (max-width: 1023px) {
  .centered-top {
    padding: 0 20px;
  }

  .custom-nav-links {
    gap: 8px;
  }

  .custom-nav-links a {
    padding: 8px 14px;
    font-size: 14px;
  }

  body.feed-view .widget.Blog .blog-posts {
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)) !important;
    gap: 24px !important;
  }

  body.item-view .widget.Blog .blog-posts .post-outer {
    padding: 32px;
  }
}

@media screen and (max-width: 768px) {
  :root {
    --nav-height: 70px;
    --radius: 16px;
  }

  .centered-top {
    flex-direction: column;
    height: auto;
    padding: 16px 20px;
    gap: 12px;
  }

  .centered-top-container {
    position: relative;
  }

  .blog-name h1 {
    font-size: 22px;
  }

  .custom-nav-links {
    width: 100%;
    justify-content: center;
  }

  .centered-bottom {
    padding: 24px 16px;
  }

  body.feed-view .widget.Blog .blog-posts {
    grid-template-columns: 1fr !important;
    gap: 20px !important;
  }

  body.feed-view .widget.Blog .post {
    padding: 20px !important;
  }

  body.feed-view .snippet-thumbnail {
    margin: -20px -20px 16px -20px;
    height: 200px;
  }

  body.item-view .widget.Blog .blog-posts .post-outer {
    padding: 24px;
  }

  .sidebar-container {
    padding: 20px;
  }

  .sidebar-container .widget {
    padding: 20px;
    margin-bottom: 20px;
  }

  .custom-dev-footer {
    padding: 32px 20px;
  }

  .custom-dev-footer .footer-links {
    flex-wrap: wrap;
    gap: 12px;
    justify-content: center;
  }

  .custom-dev-footer .footer-links a {
    padding: 10px 16px;
    font-size: 13px;
  }

  .blog-pager {
    flex-direction: column;
    gap: 12px;
  }

  .blog-pager a {
    justify-content: center;
  }
}

@media screen and (max-width: 480px) {
  body.item-view .widget.Blog .blog-posts .post-outer {
    padding: 20px;
  }

  .post-body {
    font-size: 16px;
  }

  .post-body pre {
    padding: 16px;
    font-size: 13px;
  }

  .post-title {
    font-size: 20px;
  }
}

/* ============================================
   GLASSMORPHISM SCROLLBAR
   ============================================ */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: var(--bg-solid);
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 5px;
  border: 2px solid var(--bg-solid);
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, var(--accent-hover) 0%, var(--accent-secondary) 100%);
}

/* ============================================
   GLASSMORPHISM SELECTION
   ============================================ */
::selection {
  background: rgba(0, 212, 255, 0.3);
  color: #fff;
  text-shadow: 0 0 10px rgba(0, 212, 255, 0.5);
}

::-moz-selection {
  background: rgba(0, 212, 255, 0.3);
  color: #fff;
}

/* ============================================
   GLASSMORPHISM FOCUS STATES
   ============================================ */
a:focus-visible,
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  box-shadow: 0 0 20px rgba(0, 212, 255, 0.3);
}

/* ============================================
   GLASSMORPHISM INPUT FIELDS
   ============================================ */
input[type="text"],
input[type="email"],
input[type="search"],
textarea {
  background: var(--bg-glass);
  backdrop-filter: blur(10px);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  color: var(--text);
  font-family: inherit;
  font-size: 15px;
  transition: all 0.3s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="search"]:focus,
textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 20px rgba(0, 212, 255, 0.15);
  outline: none;
}

input::placeholder,
textarea::placeholder {
  color: var(--text-muted);
}

/* ============================================
   1. NOISE TEXTURE OVERLAY
   ============================================ */
.noise-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 9999;
  opacity: 0.03;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
}

/* ============================================
   2. THEME TOGGLE
   ============================================ */
.theme-toggle {
  position: fixed;
  bottom: 30px;
  right: 30px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  border: 1px solid var(--border);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  z-index: 1000;
  transition: all 0.3s ease;
  box-shadow: var(--shadow);
}

.theme-toggle:hover {
  transform: scale(1.1);
  box-shadow: var(--shadow-glow);
  border-color: var(--accent);
}

/* Light theme variables */
body.light-theme {
  --bg: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 50%, #ddd6fe 100%);
  --bg-solid: #e0e7ff;
  --bg-card: rgba(255, 255, 255, 0.6);
  --bg-card-hover: rgba(255, 255, 255, 0.8);
  --bg-nav: rgba(255, 255, 255, 0.7);
  --bg-glass: rgba(255, 255, 255, 0.4);
  --text: rgba(15, 23, 42, 0.9);
  --text-muted: rgba(15, 23, 42, 0.6);
  --text-heading: #0f172a;
  --border: rgba(15, 23, 42, 0.1);
  --border-light: rgba(15, 23, 42, 0.2);
  --code-bg: rgba(15, 23, 42, 0.05);
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
  --shadow-hover: 0 20px 60px rgba(0, 0, 0, 0.15);
}

body.light-theme .homepage-header::before {
  background: radial-gradient(circle, rgba(0, 212, 255, 0.15) 0%, transparent 60%);
}

/* ============================================
   3. LOADING SKELETONS
   ============================================ */
.skeleton {
  background: linear-gradient(
    90deg,
    var(--bg-card) 25%,
    var(--bg-card-hover) 50%,
    var(--bg-card) 75%
  );
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
  border-radius: var(--radius-sm);
}

@keyframes skeleton-loading {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.skeleton-thumbnail {
  height: 240px;
  width: 100%;
}

.skeleton-title {
  height: 28px;
  width: 80%;
  margin-bottom: 12px;
}

.skeleton-text {
  height: 16px;
  width: 100%;
  margin-bottom: 8px;
}

.skeleton-text:last-child {
  width: 60%;
}

/* ============================================
   4. BACK TO TOP BUTTON
   ============================================ */
.back-to-top {
  position: fixed;
  bottom: 100px;
  right: 30px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--bg-card);
  backdrop-filter: var(--blur);
  border: 1px solid var(--border);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: var(--accent);
  z-index: 1000;
  transition: all 0.3s ease;
  box-shadow: var(--shadow);
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

.back-to-top.visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.back-to-top:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-glow);
  border-color: var(--accent);
  background: var(--accent-gradient);
  color: white;
}

/* ============================================
   5. READING PROGRESS BAR
   ============================================ */
.reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  width: 0%;
  height: 3px;
  background: var(--accent-gradient);
  z-index: 1001;
  transition: width 0.1s ease;
  box-shadow: 0 0 10px rgba(0, 212, 255, 0.5);
}

/* ============================================
   6. HAMBURGER MENU
   ============================================ */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: space-around;
  width: 32px;
  height: 24px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0;
  z-index: 1100;
}

.hamburger span {
  width: 100%;
  height: 3px;
  background: var(--text-heading);
  border-radius: 3px;
  transition: all 0.3s ease;
  transform-origin: center;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(7px, -6px);
}

.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 80%;
  max-width: 300px;
  height: 100vh;
  background: var(--bg-card);
  backdrop-filter: var(--blur-heavy);
  border-left: 1px solid var(--border);
  z-index: 1050;
  transition: right 0.3s ease;
  padding: 100px 32px 32px;
}

.mobile-nav.active {
  right: 0;
}

.mobile-nav-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(5px);
  z-index: 1040;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
}

.mobile-nav-overlay.active {
  opacity: 1;
  visibility: visible;
}

.mobile-nav a {
  display: block;
  padding: 16px 0;
  color: var(--text-heading);
  font-size: 18px;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
  transition: all 0.3s ease;
}

.mobile-nav a:hover {
  color: var(--accent);
  padding-left: 12px;
}

@media screen and (max-width: 768px) {
  .hamburger {
    display: flex;
  }

  .custom-nav-links {
    display: none;
  }
}

/* ============================================
   7. LAZY LOADING BLUR-UP
   ============================================ */
.lazy-image {
  opacity: 0;
  transition: opacity 0.5s ease;
}

.lazy-image.loaded {
  opacity: 1;
}

.image-placeholder {
  background: var(--bg-card);
  backdrop-filter: blur(20px);
  position: relative;
  overflow: hidden;
}

.image-placeholder::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.1),
    transparent
  );
  animation: shimmer 2s infinite;
}

/* ============================================
   8. REDUCED MOTION SUPPORT
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .homepage-header::before {
    animation: none;
  }

  .skeleton {
    animation: none;
    background: var(--bg-card);
  }

  .image-placeholder::before {
    animation: none;
  }
}

/* ============================================
   ADDITIONAL MICRO-INTERACTIONS
   ============================================ */
/* Card lift effect on scroll */
.post-outer {
  opacity: 0;
  transform: translateY(30px);
  animation: fadeInUp 0.6s ease forwards;
}

.post-outer:nth-child(1) { animation-delay: 0.1s; }
.post-outer:nth-child(2) { animation-delay: 0.2s; }
.post-outer:nth-child(3) { animation-delay: 0.3s; }
.post-outer:nth-child(4) { animation-delay: 0.4s; }
.post-outer:nth-child(5) { animation-delay: 0.5s; }
.post-outer:nth-child(6) { animation-delay: 0.6s; }

@keyframes fadeInUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Hover glow for interactive elements */
.interactive-glow {
  transition: all 0.3s ease;
}

.interactive-glow:hover {
  box-shadow: 0 0 30px rgba(0, 212, 255, 0.3);
}

/* Pulse animation for live elements */
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.pulse {
  animation: pulse 2s ease-in-out infinite;
}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible { display: inherit; }
body#layout .page { width: 60%; }
body#layout.ltr .page { float: right; }
body#layout.rtl .page { float: left; }
body#layout .sidebar-container { width: 40%; }
body#layout.ltr .sidebar-container { float: left; }
body#layout.rtl .sidebar-container { float: right; }

div.script:
// Theme Toggle
(function() {
  const themeToggle = document.getElementById('theme-toggle');
  const themeIcon = document.getElementById('theme-icon');
  const body = document.body;

  // Check for saved theme preference
  const savedTheme = localStorage.getItem('theme');
  if (savedTheme === 'light') {
    body.classList.add('light-theme');
    themeIcon.innerHTML = '☼';
  }

  themeToggle.addEventListener('click', function() {
    body.classList.toggle('light-theme');
    const isLight = body.classList.contains('light-theme');
    themeIcon.innerHTML = isLight ? '☼' : '☽';
    localStorage.setItem('theme', isLight ? 'light' : 'dark');
  });
})();

// Back to Top Button
(function() {
  const backToTop = document.getElementById('back-to-top');

  window.addEventListener('scroll', function() {
    if (window.pageYOffset > 300) {
      backToTop.classList.add('visible');
    } else {
      backToTop.classList.remove('visible');
    }
  });

  backToTop.addEventListener('click', function() {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  });
})();

// Reading Progress Bar
(function() {
  const progressBar = document.getElementById('reading-progress');
  if (!progressBar) return;

  window.addEventListener('scroll', function() {
    const scrollTop = window.pageYOffset;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const scrollPercent = (scrollTop / docHeight) * 100;
    progressBar.style.width = scrollPercent + '%';
  });
})();

// Hamburger Menu
(function() {
  const hamburger = document.getElementById('hamburger');
  const mobileNav = document.getElementById('mobile-nav');
  const mobileNavOverlay = document.getElementById('mobile-nav-overlay');

  function toggleMenu() {
    hamburger.classList.toggle('active');
    mobileNav.classList.toggle('active');
    mobileNavOverlay.classList.toggle('active');
    document.body.style.overflow = mobileNav.classList.contains('active') ? 'hidden' : '';
  }

  hamburger.addEventListener('click', toggleMenu);
  mobileNavOverlay.addEventListener('click', toggleMenu);

  // Close menu when clicking a link
  mobileNav.querySelectorAll('a').forEach(function(link) {
    link.addEventListener('click', toggleMenu);
  });
})();

// Lazy Loading Images with Blur-up Effect
(function() {
  const images = document.querySelectorAll('img[data-src]');

  const imageObserver = new IntersectionObserver(function(entries, observer) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        const img = entry.target;
        img.src = img.dataset.src;
        img.classList.add('loaded');
        observer.unobserve(img);
      }
    });
  });

  images.forEach(function(img) {
    img.classList.add('lazy-image');
    imageObserver.observe(img);
  });
})();

// Smooth scroll for anchor links
document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
  anchor.addEventListener('click', function(e) {
    const target = document.querySelector(this.getAttribute('href'));
    if (target) {
      e.preventDefault();
      target.scrollIntoView({
        behavior: 'smooth'
      });
    }
  });
});
